'use client';

import { type ReactNode, useId, useState } from 'react';
import { Button } from '@/components/ui/Button/index';
import { Icon } from '@/components/ui/Icon/index';
import { focusRing } from '@/lib/focus';
import { tv } from '@/lib/tv';
import { moveItemTo, useSortable } from './useSortable';

export { moveItemTo } from './useSortable';

export const sortableListVariants = tv({
  slots: {
    root: 'flex flex-col gap-stack-sm',
    description: 'm-0 text-body-sm text-fg-subtle',
    list: 'm-0 flex list-none flex-col gap-stack-sm p-0',
    row: [
      'flex min-w-0 flex-col rounded-md border border-border bg-surface',
      'transition-transform duration-(--8341-motion-duration-base) ease-standard',
      'forced-colors:border-[CanvasText]',
    ],
    line: 'flex min-w-0 items-center gap-gap-sm px-inset-sm py-inset-sm',
    iconButton: [
      focusRing,
      'tap-target inline-flex size-control-sm shrink-0 cursor-pointer items-center justify-center rounded-sm border-0 bg-transparent p-0',
      'hover:bg-key-subtle active:bg-key-subtle-hover',
    ],
    handle: 'cursor-grab touch-none text-icon active:cursor-grabbing',
    toggle: 'text-icon-key',
    // 桁数が変わっても項目名の位置を揃える
    number: 'min-w-[2ch] shrink-0 text-end text-body-md font-bold text-fg-subtle tabular-nums',
    content: 'min-w-0 flex-1 text-body-md break-words text-fg',
    actions: 'flex flex-wrap justify-end gap-gap-sm border-t border-border-subtle px-inset-sm py-inset-sm',
  },
  variants: {
    dragging: {
      true: { row: 'relative z-(--8341-z-dropdown) border-border-key shadow-2' },
    },
  },
});

export interface SortableListMessages {
  /** 一覧の上の操作の説明。つまみの説明として読み上げられる */
  description: string;
  /** つまみの名前 */
  handle: (name: string) => string;
  /** 行の操作を開くボタンの名前 */
  actions: (name: string) => string;
  moveUp: string;
  moveDown: string;
  remove: string;
  /** 動かしたあとの読み上げ */
  moved: (name: string, position: number, count: number) => string;
  /** 外したあとの読み上げ */
  removed: (name: string) => string;
}

const MESSAGES: SortableListMessages = {
  description:
    '左のつまみをドラッグするか、つまみにフォーカスして上下の矢印キーで並べ替えます。右のボタンからも動かせます。',
  handle: (name) => `${name}を並べ替える`,
  actions: (name) => `${name}の操作`,
  moveUp: '上へ',
  moveDown: '下へ',
  remove: '外す',
  moved: (name, position, count) => `${name}を${count}件中${position}番目に動かしました`,
  removed: (name) => `${name}を外しました`,
};

export interface SortableListProps<T> {
  /** 一覧の名前（必須）。順番つきリストの名前として読み上げられる */
  label: string;
  items: readonly T[];
  /** 項目を見分けるキー。並べ替えても変わらない値 */
  getKey: (item: T) => string;
  /** 項目の名前。つまみや操作のボタンの名前になる */
  getLabel: (item: T) => string;
  /** 並べ替えた・外したあとの並び */
  onChange: (next: T[]) => void;
  /** 行の中身。既定は getLabel の文字 */
  renderItem?: (item: T, index: number) => ReactNode;
  /** 渡すと、行の操作に「外す」が出る（onChange にも外したあとの並びが渡る） */
  onRemove?: (item: T) => void;
  /** 行の先頭に順番の数字を出す */
  numbered?: boolean;
  /** 文言の上書き（既定は日本語） */
  messages?: Partial<SortableListMessages>;
  className?: string;
}

/**
 * ドラッグとキーボードで並べ替えられる順番つきリスト。
 * 行の左のつまみをポインタでドラッグするか、つまみにフォーカスして上下の矢印キーで動かす。
 * ドラッグできない人のために、右の開閉ボタンから「上へ」「下へ」（と「外す」）も出す（WCAG 2.5.7）。
 */
export function SortableList<T>({
  label,
  items,
  getKey,
  getLabel,
  onChange,
  renderItem,
  onRemove,
  numbered = true,
  messages,
  className,
}: SortableListProps<T>) {
  const m = { ...MESSAGES, ...messages };
  const id = useId();
  const keys = items.map(getKey);
  const [announcement, setAnnouncement] = useState('');
  const { dragging, handleProps, rowRef, move, focusAfterChange } = useSortable({
    keys,
    onMove: (from, to) => {
      const item = items[from];
      onChange(moveItemTo(items, from, to));
      if (item !== undefined) setAnnouncement(m.moved(getLabel(item), to + 1, items.length));
    },
  });
  const remove = (index: number) => {
    const item = items[index];
    if (item === undefined) return;
    // 外した行の操作は消えるので、フォーカスを隣の行のつまみへ移す
    focusAfterChange(keys[index + 1] ?? keys[index - 1]);
    onChange(items.filter((_, i) => i !== index));
    onRemove?.(item);
    setAnnouncement(m.removed(getLabel(item)));
  };
  const s = sortableListVariants();
  const descriptionId = `${id}-description`;
  return (
    <div className={s.root({ className })}>
      <p id={descriptionId} className={s.description()}>
        {m.description}
      </p>
      <ol aria-label={label} className={s.list()}>
        {items.map((item, index) => {
          const key = keys[index] ?? String(index);
          return (
            <SortableRow
              key={key}
              panelId={`${id}-actions-${index}`}
              name={getLabel(item)}
              index={index}
              count={items.length}
              numbered={numbered}
              dragging={dragging === key}
              rowRef={rowRef(key)}
              handle={handleProps(key)}
              describedBy={descriptionId}
              messages={m}
              onMove={(delta) => move(index, index + delta)}
              onRemove={onRemove ? () => remove(index) : undefined}
            >
              {renderItem ? renderItem(item, index) : getLabel(item)}
            </SortableRow>
          );
        })}
      </ol>
      <div role="status" className="sr-only">
        {announcement}
      </div>
    </div>
  );
}

interface RowProps {
  panelId: string;
  name: string;
  index: number;
  count: number;
  numbered: boolean;
  dragging: boolean;
  rowRef: (element: HTMLLIElement | null) => void;
  handle: ReturnType<ReturnType<typeof useSortable>['handleProps']>;
  describedBy: string;
  messages: SortableListMessages;
  onMove: (delta: -1 | 1) => void;
  onRemove: (() => void) | undefined;
  children: ReactNode;
}

function SortableRow({
  panelId,
  name,
  index,
  count,
  numbered,
  dragging,
  rowRef,
  handle,
  describedBy,
  messages: m,
  onMove,
  onRemove,
  children,
}: RowProps) {
  const [open, setOpen] = useState(false);
  const s = sortableListVariants({ dragging });
  return (
    <li ref={rowRef} className={s.row()}>
      <div className={s.line()}>
        <button
          type="button"
          aria-label={m.handle(name)}
          aria-describedby={describedBy}
          className={s.iconButton({ className: s.handle() })}
          {...handle}
        >
          <GripIcon />
        </button>
        {numbered && (
          <span className={s.number()} aria-hidden="true">
            {index + 1}
          </span>
        )}
        <div className={s.content()}>{children}</div>
        <button
          type="button"
          aria-label={m.actions(name)}
          aria-expanded={open}
          aria-controls={panelId}
          className={s.iconButton({ className: s.toggle() })}
          onClick={() => setOpen(!open)}
        >
          <Icon name="chevron-down" className={open ? 'rotate-180' : undefined} />
        </button>
      </div>
      <div id={panelId} hidden={!open} className={s.actions()}>
        <Button
          size="sm"
          variant="secondary"
          aria-label={`${name}を${m.moveUp}`}
          disabled={index === 0}
          onClick={() => onMove(-1)}
        >
          {m.moveUp}
        </Button>
        <Button
          size="sm"
          variant="secondary"
          aria-label={`${name}を${m.moveDown}`}
          disabled={index === count - 1}
          onClick={() => onMove(1)}
        >
          {m.moveDown}
        </Button>
        {onRemove && (
          <Button size="sm" variant="tertiary" aria-label={`${name}を${m.remove}`} onClick={onRemove}>
            {m.remove}
          </Button>
        )}
      </div>
    </li>
  );
}

/** 縦に 2 列 3 段の点。つかんで動かせることを示す */
function GripIcon() {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className="size-icon-md fill-current">
      {[9, 15].flatMap((x) => [6, 12, 18].map((y) => <circle key={`${x}-${y}`} cx={x} cy={y} r={1.6} />))}
    </svg>
  );
}

'use client';

import { type KeyboardEvent, type PointerEvent, useLayoutEffect, useRef, useState } from 'react';

/** 行の縦の位置と高さ。ドラッグを始めたときに測る */
export interface Slot {
  top: number;
  height: number;
}

/** 並びの中の 1 つを、離れた位置へ一度に動かす。範囲の外を指したら元の並びを返す */
export function moveItemTo<T>(items: readonly T[], from: number, to: number): T[] {
  if (from < 0 || from >= items.length || to < 0 || to >= items.length) return [...items];
  const next = [...items];
  const [moved] = next.splice(from, 1);
  if (moved !== undefined) next.splice(to, 0, moved);
  return next;
}

/** 動かしている行の中央が、ほかの行の中央をいくつ越えたかで、入る位置を決める */
export function dropIndex(slots: readonly Slot[], from: number, dy: number): number {
  const dragged = slots[from];
  if (dragged === undefined) return from;
  const center = dragged.top + dragged.height / 2 + dy;
  return slots.filter((slot, index) => index !== from && slot.top + slot.height / 2 < center).length;
}

/** 入る位置を空けるために、ほかの行を縦にずらす量。動かしている行の高さと行の間の分だけ詰める */
export function shiftOf(slots: readonly Slot[], from: number, to: number, index: number): number {
  const dragged = slots[from];
  const [first, second] = slots;
  if (dragged === undefined || index === from) return 0;
  const gap = first !== undefined && second !== undefined ? second.top - (first.top + first.height) : 0;
  const step = dragged.height + gap;
  if (from < index && index <= to) return -step;
  if (to <= index && index < from) return step;
  return 0;
}

// 位置は style 属性ではなく CSSOM で動かす。CSP の style-src はインラインの style 属性を止めるが、スクリプトからの変更は止めない
const translate = (element: HTMLElement | undefined, y: number) => {
  if (element !== undefined) element.style.transform = y === 0 ? '' : `translateY(${y}px)`;
};

type Drag = { key: string; from: number; startY: number; slots: Slot[] };

export interface HandleProps {
  ref: (element: HTMLButtonElement | null) => void;
  onPointerDown: (event: PointerEvent<HTMLButtonElement>) => void;
  onPointerMove: (event: PointerEvent<HTMLButtonElement>) => void;
  onPointerUp: (event: PointerEvent<HTMLButtonElement>) => void;
  onPointerCancel: () => void;
  onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
}

/**
 * つまみのドラッグと上下の矢印キーでの並べ替え。
 * - ドラッグ中は行を指に付けて動かし、ほかの行は入る位置を空けるようにずらす。並びは離したときに一度で決める
 * - 並びが変わったら、前の見た目の位置から新しい位置へ動かす（FLIP）。動きを減らす設定ではテーマの規則で止まる
 * - 矢印キーで動かしたあとも、フォーカスは動かした行のつまみに残す
 */
export function useSortable({ keys, onMove }: { keys: readonly string[]; onMove: (from: number, to: number) => void }) {
  const rows = useRef(new Map<string, HTMLElement>());
  const handles = useRef(new Map<string, HTMLButtonElement>());
  const before = useRef<Map<string, number> | undefined>(undefined);
  const refocus = useRef<string | undefined>(undefined);
  const drag = useRef<Drag | undefined>(undefined);
  const [dragging, setDragging] = useState<string | undefined>(undefined);

  const measure = (): Slot[] =>
    keys.map((key) => {
      const rect = rows.current.get(key)?.getBoundingClientRect();
      return { top: rect?.top ?? 0, height: rect?.height ?? 0 };
    });

  useLayoutEffect(() => {
    const tops = before.current;
    before.current = undefined;
    if (tops !== undefined) {
      for (const [key, element] of rows.current) {
        const top = tops.get(key);
        element.style.transition = 'none';
        translate(element, top === undefined ? 0 : top - element.getBoundingClientRect().top);
        // 前の位置を一度描かせてから、遷移を戻して新しい位置へ動かす
        void element.offsetHeight;
        element.style.transition = '';
        translate(element, 0);
      }
    }
    // 行の DOM が並べ替わるとフォーカスが外れることがあるので、動かした行のつまみへ戻す
    if (refocus.current !== undefined) handles.current.get(refocus.current)?.focus();
    refocus.current = undefined;
  }, [keys]);

  /** 並びを変える。FLIP のために、変える前の位置を覚えておく */
  const move = (from: number, to: number) => {
    if (from === to || to < 0 || to >= keys.length) return;
    const slots = measure();
    before.current = new Map(keys.map((key, index) => [key, slots[index]?.top ?? 0]));
    onMove(from, to);
  };

  const follow = (current: Drag, clientY: number) => {
    const dy = clientY - current.startY;
    const to = dropIndex(current.slots, current.from, dy);
    keys.forEach((key, index) => {
      translate(rows.current.get(key), key === current.key ? dy : shiftOf(current.slots, current.from, to, index));
    });
    return to;
  };

  const release = () => {
    for (const element of rows.current.values()) {
      element.style.transition = '';
      translate(element, 0);
    }
    drag.current = undefined;
    setDragging(undefined);
  };

  const handleProps = (key: string): HandleProps => ({
    ref: (element) => {
      if (element === null) handles.current.delete(key);
      else handles.current.set(key, element);
    },
    onPointerDown: (event) => {
      if (event.button !== 0) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      drag.current = { key, from: keys.indexOf(key), startY: event.clientY, slots: measure() };
      const element = rows.current.get(key);
      // 動かしている行だけは遅れずに指に付ける
      if (element !== undefined) element.style.transition = 'none';
      setDragging(key);
    },
    onPointerMove: (event) => {
      if (drag.current?.key === key) follow(drag.current, event.clientY);
    },
    onPointerUp: (event) => {
      const current = drag.current;
      if (current?.key !== key) return;
      const to = follow(current, event.clientY);
      release();
      move(current.from, to);
    },
    onPointerCancel: release,
    onKeyDown: (event) => {
      const delta = event.key === 'ArrowUp' ? -1 : event.key === 'ArrowDown' ? 1 : 0;
      if (delta === 0) return;
      event.preventDefault();
      const from = keys.indexOf(key);
      refocus.current = key;
      move(from, from + delta);
    },
  });

  const rowRef = (key: string) => (element: HTMLElement | null) => {
    if (element === null) rows.current.delete(key);
    else rows.current.set(key, element);
  };

  /** 次に並びが変わったあと、この行のつまみへフォーカスを移す（外した行の隣へ移すときなど） */
  const focusAfterChange = (key: string | undefined) => {
    refocus.current = key;
  };

  return { dragging, handleProps, rowRef, move, focusAfterChange };
}
